test('only blank, comment-only, anchored type-only lines and identical normalized import sets are non-behavioural', () => {
  const {nonBehavioural} = require('./acceptance.cjs');
  const inert = patch => nonBehavioural(`@@\n${patch}`);
  // Inert: splitting, merging, re-ordering and re-wrapping the SAME value specifiers from the SAME module.
  assert.equal(inert('-import { A, type B } from "./x";\n+import type { B } from "./x";\n+import { A } from "./x";'), true);
  assert.equal(inert("-import {a, b} from './x';\n+import {\n+  b,\n+  a,\n+} from './x';"), true);
  assert.equal(inert("-import X, { a } from './x';\n+import { a } from './x';\n+import X from './x';"), true);
  assert.equal(inert("-import * as ns from './x';\n+import * as ns from './x'"), true);
  assert.equal(inert("-export { a } from './x';\n+export {\n+  a\n+} from './x';"), true);
  // Inert: type-only statements, anchored declarations, comments, blanks.
  assert.equal(inert("+import type { A } from './a';\n+import type B from './b';\n+import { type C, type D as E } from './c';\n+export type { F } from './f';\n+export type * from './g';"), true);
  assert.equal(inert('+export type Posted = Date | string;\n+type Local<T> = Array<T>;\n+declare type Q = typeof value;\n+interface Props { a: string; b?: number }\n+export interface Empty {}'), true);
  assert.equal(inert('+// note\n+/* one line */\n+/** doc\n+ * more words\n+ */\n+\n+;'), true);
  assert.equal(inert('--- a/x\n+++ b/x'), true);
  // Behavioural: a changed module path, a new or removed value import, a side-effect import.
  assert.equal(inert("-import {clamp} from './safe';\n+import {clamp} from './evil';"), false);
  assert.equal(inert("+import './side-effect';"), false);
  assert.equal(inert("+import { clamp } from './safe';"), false);
  assert.equal(inert("-import { clamp } from './safe';"), false);
  assert.equal(inert("-import {a} from './x';\n+import {a, b} from './x';"), false);
  assert.equal(inert("-import {a} from './x';\n+import {a as b} from './x';"), false);
  assert.equal(inert("-export * from './a';\n+export * from './b';"), false);
  assert.equal(inert("-} from './safe'\n+} from './evil'"), false);
  assert.equal(inert("-  A,\n+  B,"), false);
  // Behavioural: any trailing code after an otherwise inert statement or declaration.
  assert.equal(inert("+import x from 'y'; doEvil()"), false);
  assert.equal(inert("+import type { X } from 'y'; doEvil()"), false);
  assert.equal(inert("+import type { X } from 'y'\n+doEvil()"), false);
  assert.equal(inert('+type A = B; doEvil()'), false);
  assert.equal(inert('+type A = B\n+doEvil()'), false);
  assert.equal(inert('+type A = f();'), false);
  assert.equal(inert('+type A = { evil: 1 };'), false);
  assert.equal(inert('+/* c */ doEvil()'), false);
  assert.equal(inert('+// c\n+doEvil()'), false);
  assert.equal(inert("+interface P { a: string } doEvil()"), false);
  assert.equal(inert('+interface P {\n+  a: string;\n+}'), false);
  // Behavioural: code-shaped ` * ` lines, comment markers inside strings, comments split across hunks.
  assert.equal(inert('+  a\n+  * b'), false);
  assert.equal(inert('+ * more words'), false);
  assert.equal(inert('+x = "/*"; evil(); y = "*/"'), false);
  assert.equal(inert('+/* start\n@@\n+evil();\n+*/'), false);
  assert.equal(inert('+/* c\n+*/ evil()'), false);
  assert.equal(inert('+/* a */ run();\n+ other\n+ */'), false, 'the first closer must end the line: later closers cannot swallow code');
  assert.equal(inert('+/* a */ run();\n+*/'), false);
  assert.equal(inert('+/* a\n+ * b */\n+/* c */'), true);
  assert.equal(inert('-  author.trim().slice(0, 1)\n+  author.trim().slice(0, 2)'), false);
  assert.equal(inert('+export const behaviour = 1;'), false);
  assert.equal(nonBehavioural(undefined), false);
});

'use strict';

const fs = require('node:fs');
const path = require('node:path');
const {digest, MAX_CITATION_LINES, isCodePath, isTestPath, moduleStem, specifiersOf, coveringTests} = require('./acceptance.cjs');

function proofCatalog(snapshot) {
  return Object.entries(snapshot.sources).flatMap(([source, value], index) => {
    const lines = value.content.split('\n'); const entries = [];
    for (let start = 1; start <= lines.length; start += MAX_CITATION_LINES) {
      const end = Math.min(lines.length, start + MAX_CITATION_LINES - 1);
      if (lines.slice(start - 1, end).join('\n').trim()) entries.push({id: `proof-${index}-${start}`, source, start, end});
    }
    return entries;
  });
}

function safePath(value) {
  return typeof value === 'string' && value.length > 0 && value.length < 500 &&
    !path.posix.isAbsolute(value) && !value.includes('\\') && !value.includes('\0') &&
    !value.split('/').some(part => !part || part === '.' || part === '..' || part === '.git');
}

const BUDGET = 900000;
function evidenceSize(snapshot) {
  const value = {...snapshot}; delete value.digest;
  return JSON.stringify(value).length;
}

function refresh(snapshot) {
  const value = {...snapshot}; delete value.digest;
  if (JSON.stringify(value).length > BUDGET) throw new Error('Complete review evidence exceeds the source budget');
  snapshot.digest = digest(value);
  return snapshot;
}

async function fetchText({github, repo, snapshot, filename, ref}) {
  if (!safePath(filename)) throw Object.assign(new Error('Unsafe repository evidence path'), {unavailable: true, path: String(filename)});
  const sourceRepo = ref === snapshot.head_sha ? snapshot.head_repository : repo;
  if (!sourceRepo) throw new Error('The immutable head repository is unavailable');
  const {data} = await github.rest.repos.getContent({...sourceRepo, path: filename, ref});
  if (data.encoding !== 'base64' || typeof data.content !== 'string' || data.size > 300000) {
    throw Object.assign(new Error('Complete textual source is unavailable within the evidence budget'), {unavailable: true, path: filename});
  }
  let content;
  try {content = new TextDecoder('utf-8', {fatal: true}).decode(Buffer.from(data.content, 'base64'));}
  catch {throw Object.assign(new Error('Source is not valid UTF-8 text'), {unavailable: true, path: filename});}
  if (content.includes('\0') || content.length > 300000) throw Object.assign(new Error('Binary or oversized source is not reviewable'), {unavailable: true, path: filename});
  return content;
}

async function readSource({github, repo, snapshot, filename, ref, authority = 'untrusted', kind = 'source'}) {
  const id = `${ref}:${filename}`;
  if (snapshot.sources[id]) return id;
  snapshot.sources[id] = {path: filename, ref, authority, kind, content: await fetchText({github, repo, snapshot, filename, ref})};
  return id;
}

// A review bot rewrites the PR body with its own "Summary by <bot>" section that
// restates the diff as intent (for example "Bug Fixes: ..."). That text is a
// model's reading of the change, not the contributor's claim, and carries no
// authority; it must not be able to supply the justification for what it summarizes.
function contributorClaim(body) {
  if (typeof body !== 'string') return body;
  return body.replace(/^#{1,6} +Summary by [^\n]*(?:\n(?!#{1,6} )[^\n]*)*/gim, '').replace(/\n{3,}/g, '\n\n').trim();
}

// Optional evidence (an existing test, a source a reviewer asked for) that is missing, not
// textual, too large or beyond the evidence budget is omitted with a stated reason that the
// reviewers see. Files that actually changed never take this path: they fail closed.
async function readOptional({github, repo, snapshot, filename}) {
  try {
    const id = await readSource({github, repo, snapshot, filename, ref: snapshot.head_sha});
    if (evidenceSize(snapshot) > BUDGET) {delete snapshot.sources[id]; throw Object.assign(new Error('over budget'), {omitted: 'would exceed the total evidence budget'});}
  } catch (error) {
    const reason = error.omitted || (error.status === 404 ? 'not found at the head revision' : error.unavailable ? 'not available as complete text within the evidence budget' : null);
    if (!reason) throw error;
    snapshot.omitted_sources = [...(snapshot.omitted_sources || []).filter(item => item.path !== filename), {path: filename, reason}];
  }
}

// Supplies what pins the changed code: tests that name a changed module, importers found by content, and barrels.
// `files` are {filename, status}. The hosted review and the check of a signed local receipt use this one
// discovery, so neither applies a weaker or a stronger rule.
async function supplyTests({github, repo, snapshot, files, baseSha, headSha}) {
  // Existing tests are not part of the change, so a reviewer cannot see what pins a changed
  // module unless the controller supplies them. Tests whose path names a changed production
  // module are read at the head revision; a model's later source_request may add the rest.
  const code = files.filter(file => file.status !== 'removed' && isCodePath(file.filename));
  if (code.length) {
    const {data: tree} = await github.rest.git.getTree({...repo, tree_sha: baseSha, recursive: 'true'});
    if (tree.truncated) throw new Error('Repository tree is too large to locate the existing tests');
    const changed = new Set(files.map(file => file.filename));
    let budget = 150000;
    for (const entry of tree.tree.filter(item => item.type === 'blob' && isTestPath(item.path) && !changed.has(item.path) &&
      item.size < 60000 && code.some(file => item.path.split('/').pop().includes(moduleStem(file.filename)))).slice(0, 8)) {
      if (entry.size > budget) break;
      budget -= entry.size;
      await readOptional({github, repo, snapshot, filename: entry.path});
    }
    // Tests rarely carry the module's name (utils.test.ts imports attention-color), so importers are
    // also found by content: other small tests are read once and only their import specifiers are
    // kept, which keeps the reviewers' evidence small. Barrels that re-export a changed module's
    // directory are supplied in full so that a chain through them can be followed.
    const supplied = new Set(Object.values(snapshot.sources).map(source => source.path));
    // Real tests first, then Storybook fixtures. Each file read costs a request from the shared budget, so the
    // scan is lazy: it stops as soon as every changed code file is covered, reads real tests before stories,
    // and is bounded; the extent is stated to the reviewers.
    const story = item => /\.stories\.|(?:^|\/)stories\//.test(item.path);
    const others = tree.tree.filter(item => item.type === 'blob' && isTestPath(item.path) && !changed.has(item.path) &&
      !supplied.has(item.path) && item.size < 60000).sort((a, b) => Number(story(a)) - Number(story(b)));
    snapshot.test_imports = []; let scanned = 0;
    const uncovered = () => Object.values(coveringTests(snapshot)).some(list => !list.length);
    for (const group of [others.filter(item => !story(item)), others.filter(story)]) {
      for (let offset = 0; offset < group.length && scanned < 100 && uncovered(); offset += 10) {
        const batch = group.slice(offset, offset + Math.min(10, 100 - scanned));
        scanned += batch.length;
        const found = await Promise.all(batch.map(async entry => {
          try {return {path: entry.path, specifiers: specifiersOf(await fetchText({github, repo, snapshot, filename: entry.path, ref: headSha}))};}
          catch (error) {if (error.status === 404 || error.unavailable) return null; throw error;}
        }));
        snapshot.test_imports.push(...found.filter(item => item && item.specifiers.length));
      }
    }
    snapshot.importer_scan = {tests_found: others.length, tests_scanned: scanned};
    const directories = new Set(code.flatMap(file => file.filename.split('/').slice(0, -1).map((_, i, parts) => parts.slice(0, parts.length - i).join('/'))));
    for (const entry of tree.tree.filter(item => item.type === 'blob' && !changed.has(item.path) && /(?:^|\/)index\.[cm]?[jt]sx?$/.test(item.path) &&
      directories.has(item.path.split('/').slice(0, -1).join('/')) && item.size < 60000).slice(0, 6)) {
      await readOptional({github, repo, snapshot, filename: entry.path});
    }
  }
  snapshot.covering_tests = coveringTests(snapshot);
  return snapshot;
}

async function collectSnapshot({github, repo, pr, files, config, technical, intentConfirmation = null}) {
  if (!files.length || files.length !== pr.changed_files || files.some(file =>
    !safePath(file.filename) || !file.patch || !['added', 'modified', 'removed', 'renamed'].includes(file.status))) {
    throw new Error('Changed-file evidence is incomplete');
  }
  const policy = fs.readFileSync(path.join(__dirname, '../policy/change-acceptance.md'), 'utf8');
  if (!pr.head.repo?.owner?.login || !pr.head.repo.name) throw new Error('The immutable head repository is unavailable');
  const snapshot = {version: 2, review_manifest_version: 1, repository: `${repo.owner}/${repo.repo}`, number: pr.number,
    base_sha: pr.base.sha, head_sha: pr.head.sha, paths: files.map(file => file.filename).sort(),
    head_repository: {owner: pr.head.repo.owner.login, repo: pr.head.repo.name},
    config_digest: digest(config), policy_digest: digest(policy), sources: {}, files: [], history: [], tickets: []};
  snapshot.sources['verification'] = {authority: 'trusted', kind: 'verification', path: 'verification', ref: pr.head.sha,
    content: JSON.stringify(technical, null, 2)};
  for (const filename of [config.repository_policy, config.readme]) {
    await readSource({github, repo, snapshot, filename, ref: pr.base.sha, authority: 'trusted', kind: 'contract'});
  }
  snapshot.intent_confirmation = intentConfirmation;
  if (intentConfirmation) {
    const ref = digest(intentConfirmation);
    snapshot.sources[`intent:${ref}`] = {path: `pulls/${pr.number}/intent/${intentConfirmation.comment_id}`, ref,
      authority: 'trusted', kind: 'contract', content: JSON.stringify(intentConfirmation, null, 2)};
  }
  for (const file of files) {
    const item = {path: file.filename, status: file.status, patch: file.patch};
    if (file.status !== 'added') {
      const filename = file.previous_filename || file.filename;
      item.base_source = await readSource({github, repo, snapshot, filename, ref: pr.base.sha});
      const {data} = await github.rest.repos.listCommits({...repo, path: filename, sha: pr.base.sha, per_page: 3});
      snapshot.history.push({path: filename, commits: data.map(commit => ({sha: commit.sha, message: commit.commit.message}))});
    }
    if (file.status !== 'removed') item.head_source = await readSource({github, repo, snapshot, filename: file.filename, ref: pr.head.sha});
    snapshot.files.push(item);
  }
  await supplyTests({github, repo, snapshot, files, baseSha: pr.base.sha, headSha: pr.head.sha});
  const linked = await github.graphql(`query($owner:String!,$repo:String!,$number:Int!) {
    repository(owner:$owner,name:$repo) { pullRequest(number:$number) {
      closingIssuesReferences(first:10) { nodes { number title body url author { login } } pageInfo { hasNextPage } }
    } }
  }`, {...repo, number: pr.number});
  const tickets = linked.repository.pullRequest.closingIssuesReferences;
  if (tickets.pageInfo.hasNextPage) throw new Error('Linked requirement evidence is incomplete');
  snapshot.tickets = tickets.nodes;
  for (const ticket of snapshot.tickets) {
    const ref = digest(ticket);
    snapshot.sources[`ticket:${ticket.number}:${ref}`] = {path: `issues/${ticket.number}`, ref,
      authority: 'untrusted', kind: 'requirement', content: JSON.stringify(ticket, null, 2)};
  }
  snapshot.claims = {title: pr.title, description: contributorClaim(pr.body)};
  return refresh(snapshot);
}

async function additionalSources({github, repo, snapshot, paths}) {
  if (!Array.isArray(paths) || paths.length === 0 || paths.length > 8 || new Set(paths).size !== paths.length) {
    throw new Error('Additional evidence requires one to eight distinct repository paths');
  }
  for (const filename of paths) await readOptional({github, repo, snapshot, filename});
  snapshot.covering_tests = coveringTests(snapshot);
  return refresh(snapshot);
}

module.exports = {supplyTests, contributorClaim, proofCatalog, safePath, refresh, readSource, collectSnapshot, additionalSources};

'use strict';

const {test} = require('node:test');
const assert = require('node:assert/strict');
const {proofCatalog, safePath, refresh, readSource, collectSnapshot, additionalSources} = require('./acceptance-sources.cjs');
const {packetFor} = require('./acceptance-grading.cjs');

test('controller proof IDs bind bounded immutable spans and remain stable when source context grows', () => {
  const snapshot = {sources: {blank: {content: '\n'}, code: {content: Array.from({length: 85}, (_, i) =>
    i < 40 ? '' : `statement ${i + 1}`).join('\n')}}};
  const proofs = proofCatalog(snapshot);
  assert.deepEqual(proofs, [{id: 'proof-1-41', source: 'code', start: 41, end: 80},
    {id: 'proof-1-81', source: 'code', start: 81, end: 85}]);
  snapshot.sources.other = {content: 'additional source'};
  assert.deepEqual(proofCatalog(snapshot).slice(0, 2), proofs);
});

function fixture() {
  const calls = [];
  const tree = {truncated: false, tree: [
    {type: 'blob', path: 'tests/upload.test.rs', size: 100}, {type: 'blob', path: 'tests/other.test.rs', size: 100},
    {type: 'blob', path: 'tests/upload.huge.test.rs', size: 70000}, {type: 'tree', path: 'tests/upload.dir.test.rs'},
    {type: 'blob', path: 'src/upload.rs', size: 10}, {type: 'blob', path: 'src/upload.test.rs', size: 100000}]};
  const github = {rest: {git: {getTree: async args => ({data: structuredClone(github.tree), args})}, repos: {
    getContent: async args => {calls.push(args); return {data: {content: Buffer.from('A complete fictional source.\n').toString('base64'), encoding: 'base64', size: 30}};},
    listCommits: async () => ({data: [{sha: 'b'.repeat(40), commit: {message: 'fix: preserve durable upload acceptance'}}]}),
  }}, graphql: async () => ({repository: {pullRequest: {closingIssuesReferences: {nodes: [{number: 1, title: 'Repair upload', body: 'Preserve acceptance.'}], pageInfo: {hasNextPage: false}}}}})};
  github.tree = tree;
  return {github, calls, repo: {owner: 'example', repo: 'upload-gateway'},
    pr: {number: 3, changed_files: 1, title: 'fix: preserve upload', body: 'Untrusted contributor claim.', base: {sha: 'b'.repeat(40)}, head: {sha: 'a'.repeat(40), repo: {owner: {login: 'external'}, name: 'fork'}}},
    files: [{filename: 'src/upload.rs', status: 'modified', patch: '@@ -1 +1 @@\n-old\n+new'}],
    config: {repository_policy: '.github/clouseau.md', readme: 'README.md'},
    technical: {run_id: 42, head_sha: 'a'.repeat(40), conclusion: 'success'}};
}

test('source collection binds complete base/head blobs, authority, precedent, tickets and runtime identity', async () => {
  const f = fixture();
  const snapshot = await collectSnapshot(f);
  assert.equal(snapshot.repository, 'example/upload-gateway');
  assert.equal(snapshot.head_sha, f.pr.head.sha); assert.equal(snapshot.base_sha, f.pr.base.sha);
  assert.match(snapshot.digest, /^[a-f0-9]{64}$/);
  assert.equal(snapshot.sources[`${f.pr.base.sha}:README.md`].authority, 'trusted');
  assert.equal(snapshot.sources[`${f.pr.head.sha}:src/upload.rs`].authority, 'untrusted');
  assert.equal(snapshot.files[0].base_source, `${f.pr.base.sha}:src/upload.rs`);
  assert.equal(snapshot.sources.verification.authority, 'trusted');
  assert.equal(JSON.parse(snapshot.sources.verification.content).run_id, 42);
  assert.equal(snapshot.history[0].commits[0].message, 'fix: preserve durable upload acceptance');
  assert.equal(snapshot.tickets[0].number, 1);
  assert.equal(snapshot.claims.description, f.pr.body);
  const digest = snapshot.digest;
  await additionalSources({...f, snapshot, paths: ['src/naming.rs']});
  assert.notEqual(snapshot.digest, digest);
  assert.equal(snapshot.sources[`${f.pr.head.sha}:src/naming.rs`].authority, 'untrusted');
  const count = f.calls.length;
  await additionalSources({...f, snapshot, paths: ['src/naming.rs']});
  assert.equal(f.calls.length, count, 'immutable evidence is not refetched');
  assert.ok(f.calls.every(call => [f.pr.head.sha, f.pr.base.sha].includes(call.ref)));
  assert.ok(f.calls.filter(call => call.ref === f.pr.head.sha).every(call => call.owner === 'external' && call.repo === 'fork'));
  assert.ok(f.calls.filter(call => call.ref === f.pr.base.sha).every(call => call.owner === 'example'));
});

test('renamed, added and removed files use only their applicable immutable sources', async () => {
  for (const status of ['renamed', 'added', 'removed']) {
    const f = fixture(); f.files[0].status = status;
    if (status === 'renamed') f.files[0].previous_filename = 'src/old.rs';
    const snapshot = await collectSnapshot(f);
    assert.equal(Boolean(snapshot.files[0].base_source), status !== 'added');
    assert.equal(Boolean(snapshot.files[0].head_source), status !== 'removed');
    assert.equal(snapshot.history.length, status === 'added' ? 0 : 1);
    if (status === 'renamed') assert.ok(snapshot.files[0].base_source.endsWith(':src/old.rs'));
  }
});

test('linked requirements survive source collection, proof selection and atomic grading without gaining authority', async () => {
  const f = fixture();
  const request = {number: 27, title: 'Support the active native coverage consumer',
    body: 'The existing consumer produces Istanbul JSON. Preserve its complete source inventory.',
    url: 'https://github.com/example/upload-gateway/issues/27', author: {login: 'maintainer'}};
  f.github.graphql = async () => ({repository: {pullRequest: {closingIssuesReferences: {
    nodes: [request], pageInfo: {hasNextPage: false}}}}});
  const snapshot = await collectSnapshot(f);
  const proof = proofCatalog(snapshot).find(item => snapshot.sources[item.source].kind === 'requirement');
  assert.ok(proof, 'a linked request must be citable, not stranded outside the proof catalog');
  const source = snapshot.sources[proof.source];
  assert.equal(source.authority, 'untrusted', 'issue authorship cannot grant contract or execution authority');
  assert.deepEqual(JSON.parse(source.content), request);
  const location = {subject: request.title, obligation: 'Preserve exact native coverage', context: {},
    target: {reason: 'The linked request describes the active consumer limitation.', evidence: [proof.id]}};
  const report = {evidence: [proof]};
  const packet = packetFor(location, report, snapshot);
  assert.equal(packet.evidence[0].text, source.content);
  assert.equal(packet.evidence[0].authority, 'untrusted');
  assert.match(packet.evidence[0].text, /Preserve its complete source inventory/);
  request.body = 'Updated requirement; do not reuse the prior assessment.';
  const updated = await collectSnapshot(f);
  const next = proofCatalog(updated).find(item => updated.sources[item.source].kind === 'requirement');
  assert.notEqual(updated.digest, snapshot.digest);
  assert.notEqual(next.source, proof.source, 'changed issue content gets a new immutable source identity');
  assert.notEqual(updated.sources[next.source].ref, source.ref);
});

test('bounded source reader refuses path traversal, binary data, truncation and invalid UTF-8', async () => {
  for (const value of [null, '', '/tmp/code', '../code', 'a/../code', 'a/./code', '.git/config', 'a//b', 'a\\b', 'a\0b', 'x'.repeat(500)]) assert.equal(safePath(value), false);
  assert.equal(safePath('src/module.rs'), true);
  const f = fixture();
  await assert.rejects(readSource({...f, snapshot: {sources: {}}, filename: '../private', ref: f.pr.head.sha}), /Unsafe/);
  await assert.rejects(readSource({...f, snapshot: {sources: {}, head_sha: f.pr.head.sha}, filename: 'src/upload.rs', ref: f.pr.head.sha}), /head repository/);
  for (const data of [{}, {content: '', encoding: 'utf8'}, {content: '', encoding: 'base64', size: 300001},
    {content: Buffer.from('x'.repeat(300001)).toString('base64'), encoding: 'base64'},
    {content: Buffer.from('a\0b').toString('base64'), encoding: 'base64'},
    {content: Buffer.from([0xff]).toString('base64'), encoding: 'base64'}]) {
    f.github.rest.repos.getContent = async () => ({data});
    await assert.rejects(readSource({...f, snapshot: {sources: {}}, filename: 'src/module.rs', ref: f.pr.head.sha}));
  }
});

test('incomplete evidence, unsafe prior paths, oversized packets and truncated linked requirements fail closed', async () => {
